SHELL=/bin/bash
MAILTO=""

*/15 2 * * 1-5 /usr/bin/backup --quiet
0 4 1,15 * * /usr/local/bin/report >/var/log/report.log 2>&1
30 22 * * 0 /usr/local/bin/weekly-maintenance
@daily /usr/bin/cleanup-tmp
@weekly /usr/local/bin/prune-archives
@reboot /usr/local/bin/boot-hook

#!/usr/bin/env python3
"""cronlint - a small linter for crontab files.

Understands:
  * comments (# ...) and blank lines
  * NAME=value environment assignment lines
  * @aliases: @reboot, @yearly, @annually, @monthly, @weekly,
    @daily, @midnight, @hourly
  * standard 5-field schedules followed by a command

Each problem is reported as ``LINE: message`` on stdout.
Exit status is 1 if any problems were found, 0 otherwise.
"""

from __future__ import annotations

import re
import sys

ALIASES = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
    # @reboot has no schedule fields; only the presence of a command matters.
}

FIELD_NAMES = ("minute", "hour", "day of month", "month", "day of week")
FIELD_RANGES = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 7))

ENV_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=(.*)$")


class LintError(Exception):
    """A problem found in a single crontab line."""


def _check_atom(atom: str, lo: int, hi: int, field: str) -> None:
    """Validate a single (non-comma) component of a cron field."""
    step = atom.split("/", 1)
    base = step[0]
    if len(step) == 2:
        if not re.fullmatch(r"\d+", step[1]):
            raise LintError(f"{field} field: invalid step '{step[1]}'")
    if base == "*":
        return
    m = re.fullmatch(r"(\d+)(?:-(\d+))?", base)
    if not m:
        raise LintError(f"{field} field: invalid value '{base}'")
    first = int(m.group(1))
    last = int(m.group(2)) if m.group(2) else first
    if not lo <= first <= hi or not lo <= last <= hi:
        raise LintError(f"{field} field: {base} out of range ({lo}-{hi})")
    if last < first:
        raise LintError(f"{field} field: invalid range {base}")


def check_field(spec: str, index: int) -> None:
    """Validate one schedule field against its allowed range."""
    lo, hi = FIELD_RANGES[index]
    field = FIELD_NAMES[index]
    for atom in spec.split(","):
        if atom == "":
            raise LintError(f"{field} field: empty list element")
        _check_atom(atom, lo, hi, field)


def lint_line(lineno: int, line: str, errors: list[str]) -> None:
    def err(message: str) -> None:
        errors.append(f"{lineno}: {message}")

    if line.startswith("#"):
        return

    env = ENV_RE.match(line)
    if env:
        # An assignment must actually have something after the '=' unless it
        # is deliberately empty (NAME= with nothing is unusual but legal).
        return

    tokens = line.split()
    if not tokens:
        return  # blank line

    head = tokens[0]
    if head in ALIASES:
        if len(tokens) < 2:
            err("missing command")
        elif head == "@reboot":
            pass
        else:
            for i, spec in enumerate(ALIASES[head].split()):
                check_field(spec, i)
        return

    if head.startswith("@"):
        err(f"unknown alias '{head}'")
        return

    if len(tokens) < 5:
        err(f"wrong field count: expected at least 5 schedule fields, got {len(tokens)}")
        return
    if len(tokens) == 5:
        for i, spec in enumerate(tokens[:5]):
            try:
                check_field(spec, i)
            except LintError as exc:
                err(str(exc))
        err("missing command")
        return

    for i, spec in enumerate(tokens[:5]):
        try:
            check_field(spec, i)
        except LintError as exc:
            err(str(exc))


def lint(path: str) -> list[str]:
    errors: list[str] = []
    with open(path, encoding="utf-8") as fh:
        for lineno, raw in enumerate(fh, start=1):
            lint_line(lineno, raw.rstrip("\n"), errors)
    return errors


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print("usage: cronlint.py CRONTAB_FILE", file=sys.stderr)
        return 2
    try:
        errors = lint(argv[1])
    except OSError as exc:
        print(f"cronlint: cannot read {argv[1]}: {exc}", file=sys.stderr)
        return 2
    for message in errors:
        print(message)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

